 iso42001:{title:'ISO/IEC 42001:2023 · public overview',org:'ISO',url:'https://www.iso.org/standard/42001',kind:'Certifiable AI management-system standard',excerpt:'continually improving an Artificial Intelligence Management System',excerptAt:'ISO public overview; not a quotation from the paid standard',activity:'Read the public overview. Draft a system inventory, accountable owner, evaluation plan, and change-review record.'},
