 hygiene:{title:'Cybersecurity basics for small businesses',org:'NIST · current guidance',url:'https://www.nist.gov/itl/smallbusinesscyber/cybersecurity-basics',kind:'Everyday security guidance',activity:'Choose one account, one device, and one recovery method. Check MFA, patching, and a usable recovery path.'}
