window.WINTERWATCH_LESSONS = [
{id:1,title:'Even the fridge needs a firewall',short:'The fridge attack',category:'ot',icon:'snowflake',kind:'Observed incidents',minutes:6,
 summary:'ENISA reports refrigeration incidents in EU countries from 11 October 2026, with a renewed wave on 1–2 November. CERT-FR identifies affected controller families; internet-facing management is a central exposure. Attribution and the entry route for every affected installation remain unresolved.',
 failure:'A physical business process depended on remotely reachable management. An exposed controller can become a route to unsafe configuration changes.',takeaway:'Protect the cold chain like a critical system.',
 timeline:[['11 Oct 2026','Incidents begin, according to ENISA.'],['12–16 Oct','CERT-FR publishes and updates its controller alert.'],['1–2 Nov','A new incident wave is recorded.'],['4 Nov','ENISA issues a coordinated statement.']],
 lenses:{technical:'Map controller management paths, remove direct internet exposure, and broker supplier access through a protected gateway.',business:'Name an accountable cold-chain owner. Fund supported controllers and an alternative operating plan.',operations:'Verify setpoints, defrost schedules and alarms against an approved baseline with the refrigeration engineer.'},
 steps:['Collect firewall flows, remote-access logs and controller configuration changes; add an asset and supplier owner.','Deny direct public management; allow approved maintenance through a secured gateway. Apply supported firmware and unique credentials.','Route an unexpected setpoint, defrost or alarm-disable change to both the SOC and the on-duty facilities lead.'],
 logic:'WHEN controller_configuration_changes\nAND (no_approved_change OR source_not_approved)\nTHEN alert SOC + facilities; preserve old/new values',test:'Replay a synthetic configuration-change event in a test SIEM. Never change a live fridge temperature to test an alert.',noise:'Scheduled maintenance and approved defrost changes. Missing logs require independent temperature monitoring.',
 response:['Facilities · Check independent temperature readings and protect goods using the approved safety procedure.','Network team · Remove unsafe remote exposure in coordination with facilities and the service provider.','SOC · Preserve configuration, access logs and the incident timeline; investigate related controllers.','Incident lead · Restore a trusted configuration, validate alarms, and assess supplier and authority notifications.'],
 mission:['Identify one fictional controller, its owner, and its support status.','Mark its approved remote-access route on a sketch.','Name who receives an out-of-range temperature alert at 02:00.'],quiz:{q:'What is the strongest first exposure control?',a:['Reset the controller and leave the public interface online.','Remove direct public management and use controlled remote access.','Wait for an attacker name before acting.'],correct:1,why:'A reset does not close the original exposure. Coordinate isolation with safe physical operations.'},sources:['enisa','fridge','cold']},
{id:2,title:'The supplier has a key, too',short:'Supplier access',category:'ot',icon:'key',kind:'Control workshop',minutes:5,
 summary:'The refrigeration advisories recommend protected remote access and configuration review. A customer and its maintenance supplier share operational dependencies: the customer must know who can connect, and the supplier needs a safe, approved way to maintain the system.',failure:'Shared vendor accounts, undocumented modems and indefinite maintenance access create blind spots.',takeaway:'Make every supplier connection owned and revocable.',
 timeline:[['Before access','Record purpose, owner, permitted assets and maintenance window.'],['During access','Log identity, session and approved change.'],['After access','Remove temporary permission and compare configurations.']],lenses:{technical:'Use named, time-limited supplier accounts, MFA at the access gateway, and session logging.',business:'Contract for notification, evidence access, support lifecycle, sub-suppliers and exit assistance.',operations:'Keep an offline vendor contact and a jointly tested emergency isolation procedure.'},
 steps:['Inventory supplier accounts and gateways; link each to a customer-side owner.','Restrict routes to required controllers and approved time windows; alert on vendor access outside those boundaries.','Review dormant accounts and confirm revocation works without losing essential monitoring.'],logic:'WHEN vendor_session_started\nAND (outside_approved_window OR destination_not_in_contract)\nTHEN notify customer owner + supplier contact',test:'Use a dedicated test account to request an out-of-window session in a lab.',noise:'Emergency maintenance needs an explicit exception and a post-event review.',response:['Service owner · Verify the supplier through a known contact.','Access team · Suspend the affected connection; preserve session evidence.','Facilities · Check operations and monitoring continuity.','Procurement · Review notification, audit and exit commitments with the supplier.'],mission:['Draft three access conditions for a fictional supplier.','Write a revocation owner and fallback contact.','Rehearse an access-removal request on paper.'],quiz:{q:'Which supplier-access record is most useful?',a:['A shared password in a team chat.','An account name with no expiry.','Named owner, defined scope, expiry and a tested revocation path.'],correct:2,why:'An access grant must remain accountable throughout its lifecycle.'},sources:['cold','nis','dora']},
{id:3,title:'One token, many open doors',short:'The OAuth domino',category:'cyber',icon:'key',kind:'Observed campaign',minutes:6,
 summary:'GTIG reports that compromised Salesloft Drift OAuth tokens were used to export Salesforce data on 8–18 August 2025. Its 28 August update expanded concern to other connected integrations. The actor searched stolen data for additional secrets; GTIG says this did not stem from a core Salesforce vulnerability.',failure:'A trusted integration and credentials stored in business records expanded the blast radius.',takeaway:'Treat integrations as privileged identities.',timeline:[['8–18 Aug 2025','Customer Salesforce data is accessed and exported.'],['20 Aug','Drift access and refresh tokens are revoked.'],['28 Aug','GTIG expands guidance to all connected authentication tokens.']],lenses:{technical:'Inventory OAuth grants, export API audit events, and hunt for downstream use of secrets in exposed records.',business:'Ask each SaaS owner which services and data their integrations can reach.',operations:'Practise disabling a connector while keeping a manual business workflow available.'},steps:['Ingest OAuth grant, API export and connector-admin logs into the SIEM.','Alert when an integration identity exports an unusual volume of records or accesses new objects; baseline per application.','Revoke affected tokens, rotate exposed downstream secrets, and verify that replacement scopes are necessary.'],logic:'WHEN integration_export_volume > application_baseline\nOR integration_accesses_new_sensitive_object\nTHEN alert app owner + SOC; attach grant and token metadata',test:'Generate a small synthetic export in a test tenant and verify that the alert includes the app identity.',noise:'Backfills and migrations; approve them with owners rather than suppressing all connector traffic.',response:['SaaS owner · Revoke the affected integration grants and preserve audit logs.','SOC · Scope objects, records, time windows and downstream secrets.','Secret owners · Rotate exposed keys and investigate their use.','Privacy / communications · Assess affected data, contracts, and applicable reporting duties.'],mission:['List three integrations for a fictional CRM.','Identify one secret that must never go into a support ticket.','Write the exact owner for connector revocation.'],quiz:{q:'Does resetting a user password reliably revoke all OAuth access?',a:['Yes, all third-party grants disappear.','No. Review and revoke affected grants and tokens explicitly.','Only if the password is longer than 20 characters.'],correct:1,why:'Tokens and integration grants need their own containment and investigation.'},sources:['drift']},
{id:4,title:'The gift hidden in a dependency',short:'Supply-chain surprise',category:'cyber',icon:'gift',kind:'Observed supply-chain attack',minutes:6,
 summary:'GitHub says it was notified of Shai-Hulud on 14 September 2025. Compromised maintainer accounts distributed malicious npm post-install scripts that stole secrets and propagated. Dependency installation was part of the attack surface.',failure:'Code fetched during a routine build inherited access to valuable credentials.',takeaway:'Install dependencies where production secrets cannot follow.',timeline:[['14 Sep 2025','GitHub is notified of the worm.'],['Sep 2025','Malicious packages are removed and ecosystem response begins.'],['Your next build','Re-evaluate installation, publishing identity and runner trust.']],lenses:{technical:'Constrain install scripts where compatible, isolate runners and use short-lived publishing identities.',business:'Ask whether build systems can publish, deploy and read production data with the same credentials.',operations:'Keep a dependency incident inventory and a clean-runner recovery procedure.'},steps:['Record the package lockfile, installation process, runner identity and outgoing connections.','Keep install jobs free of production secrets; minimise workflow permissions and review dependency changes.','Alert on install processes accessing credential files or publishing unexpected package versions.'],logic:'WHEN dependency_install_process\nAND (credential_store_read OR unexpected_outbound_destination\n     OR unapproved_package_publish)\nTHEN alert build owner; quarantine runner evidence',test:'Use dummy credential files and a local mock destination in an isolated runner.',noise:'Some legitimate build hooks run compilers or fetch binaries; baseline approved behaviour.',response:['Build owner · Stop affected jobs and preserve runner and package evidence.','Security · Identify installed versions and systems that executed them.','Credential owners · Revoke accessible secrets and inspect downstream use.','Release lead · Rebuild on trusted runners and validate provenance before release.'],mission:['Draw a build job’s credential boundary.','Remove a fictional production key from its install stage.','Choose who can halt a compromised release.'],quiz:{q:'Which boundary limits dependency-install damage?',a:['An isolated install job with no production secrets.','A lockfile with no monitoring.','A long-lived administrator token for convenience.'],correct:0,why:'A lockfile helps reproducibility; isolation limits what an executed package can reach.'},sources:['npm']},
{id:5,title:'Patched does not always mean clean',short:'Beyond the patch',category:'cyber',icon:'shield',kind:'Observed exploitation',minutes:7,
 summary:'Microsoft’s July 2025 ToolShell analysis describes exploitation of on-premises SharePoint, web-shell deployment and theft of ASP.NET machine keys. SharePoint Online was not affected by these vulnerabilities. Recovery guidance includes comprehensive updates, machine-key rotation and restarting IIS.',failure:'Exploitation could create persistence and expose signing material that survives a simple patch.',takeaway:'Close the entry point and remove the foothold.',timeline:[['7 Jul 2025','Microsoft assesses attempted exploitation as early as this date.'],['19 Jul','Microsoft publishes active-attack guidance.'],['22–23 Jul','Technical analysis and recovery guidance expand.']],lenses:{technical:'Use current vendor recovery instructions, EDR hunting and key rotation alongside patching.',business:'Track exposure, investigation and recovery confidence separately from patch completion.',operations:'Plan a recovery window, business fallback and evidence preservation before restart.'},steps:['Ingest IIS logs, ASPX file writes, EDR process trees and security-control health.','Alert on SharePoint worker processes creating suspicious script files or launching command shells.','Apply current supported updates and vendor recovery guidance; rotate keys and restart IIS as instructed.'],logic:'WHEN parent_process == "w3wp.exe"\nAND (child_is_unexpected_shell OR unexpected_ASPX_write)\nTHEN investigate on-premises SharePoint host',test:'Replay an authorised synthetic process-tree fixture; do not deploy a web shell.',noise:'Administrative activity can spawn tools. Restrict exceptions to documented maintenance.',response:['SOC · Preserve host, web and identity evidence.','Platform owner · Contain the affected host and assess lateral movement.','Recovery lead · Patch, eradicate persistence, rotate exposed keys and follow current restart guidance.','Service owner · Validate functionality and monitored recovery before reopening access.'],mission:['Separate patch, eradication and validation on a recovery checklist.','Find an owner for application signing keys.','Record a safe rollback and business fallback.'],quiz:{q:'Why might patching alone be insufficient?',a:['Patching always deletes attacker activity.','Attackers may retain persistence or stolen key material.','SharePoint Online has the same exposure.'],correct:1,why:'The case involved on-premises systems, persistence and exposed machine keys.'},sources:['shell','mde']},
{id:6,title:'A stolen password is still a key',short:'Cloud identity hygiene',category:'privacy',icon:'snowflake',kind:'Observed customer breaches',minutes:6,
 summary:'Mandiant’s June 2024 UNC5537 investigation traced customer Snowflake compromises to stolen customer credentials. The campaign involved accounts without MFA, still-valid stolen credentials and missing network allowlists. It found no evidence that the access originated from a breach of Snowflake’s enterprise environment.',failure:'Valid credentials, insufficient authentication controls and data access enabled theft.',takeaway:'Secure the identity that can reach the data.',timeline:[['Apr 2024','Mandiant investigates a customer instance compromise.'],['22 May','A broader campaign is identified.'],['30 May','Snowflake publishes hardening guidance.'],['10 Jun','Mandiant publishes its investigation.']],lenses:{technical:'Enforce strong MFA for people, scoped workload authentication and network restrictions appropriate to the service.',business:'Request evidence of identity controls and data-access boundaries in the customer environment.',operations:'Track dormant accounts, contractor offboarding and unusual exports.'},steps:['Collect authentication, query and export logs with identity and source context.','Correlate new-source login with unusual access to sensitive datasets or bulk export.','Review service-account privileges, MFA exceptions and network policy with the data owner.'],logic:'WHEN successful_login_from_new_source\nFOLLOWED BY sensitive_data_export_above_baseline\nWITHIN 30 minutes\nTHEN alert identity owner + data owner',test:'Replay synthetic login and export events; use a dummy dataset only.',noise:'Approved analytics jobs, travel and scheduled exports; thresholds need per-workload tuning.',response:['Identity team · Disable or restrict the identity and revoke active access.','SOC · Investigate endpoint credential theft and account history.','Data owner · Scope accessed datasets and recipients.','Privacy lead · Assess people’s risk and record the notification decision.'],mission:['Check MFA on a personal or test account you own.','Name the owner of one fictional bulk-export job.','Write a documented exception expiry.'],quiz:{q:'What did the cited investigation establish?',a:['All Snowflake infrastructure was breached.','Customer credentials were the route in the investigated cases.','MFA cannot help protect data services.'],correct:1,why:'Avoid confusing a customer identity compromise with a provider infrastructure breach.'},sources:['snowflake','hygiene']},
{id:7,title:'Trust the transaction, not just the screen',short:'The trusted-screen trap',category:'cyber',icon:'star',kind:'Affected-party forensic account',minutes:5,
 summary:'Bybit’s 26 February 2025 preliminary update says compromised Safe developer credentials allowed attackers to alter Safe infrastructure and deceive signers into approving a malicious transaction. The statement reports no indication of compromise within Bybit infrastructure.',failure:'Several approvals can share the same compromised view of an action.',takeaway:'Verify high-impact actions through an independent path.',timeline:[['Feb 2025','A malicious wallet transaction is approved.'],['26 Feb','Bybit publishes preliminary forensic findings.'],['Before your next approval','Verify destination and actual action independently.']],lenses:{technical:'Protect release infrastructure and verify decoded transaction intent through an independent trusted mechanism.',business:'Require independent checks for exceptional payments and beneficiary changes.',operations:'A familiar screen or voice does not replace a verified callback and dual control.'},steps:['Log high-value action requests, decoded intent, approvers and independent verification evidence.','Require a second trusted verification path for changed beneficiaries or unusual transactions.','Alert on privileged changes to the approval application or release pipeline.'],logic:'WHEN high_impact_action\nAND (beneficiary_changed OR independent_verification_missing)\nTHEN hold for authorised review',test:'Use a fictional payment and a mock changed beneficiary in a tabletop.',noise:'Legitimate urgent payments still need a documented exception and independent approval.',response:['Finance / operations · Pause the action and verify through a known contact.','SOC · Preserve application versions, identity and approval evidence.','Supplier owner · Coordinate investigation of the upstream approval surface.','Incident lead · Assess exposure and engage relevant authorities and counterparties.'],mission:['Choose a known callback route for a fictional payment change.','Write what a second approver must verify independently.','Set an escalation owner for urgent exceptions.'],quiz:{q:'Do three approvers guarantee safety if all see one compromised interface?',a:['Yes, three clicks are sufficient.','Only during working hours.','No. They may all approve the same false representation.'],correct:2,why:'Independent verification must add evidence beyond repeating the same view.'},sources:['bybit']},
{id:8,title:'A helpful voice at the help desk',short:'Verify before you reset',category:'cyber',icon:'bell',kind:'Campaign / TTP advisory',minutes:5,
 summary:'The July 2025 joint Scattered Spider advisory describes recurring social engineering, identity resets, MFA abuse and remote-access techniques. It is a campaign advisory, not a report of one named victim incident.',failure:'A support workflow can grant an attacker a new authentication path.',takeaway:'Make recovery as strong as normal sign-in.',timeline:[['Before a request','Define privileged reset proof and escalation.'],['29 Jul 2025','Authorities update the campaign advisory.'],['At a suspicious reset','Preserve the request, verify independently, and investigate subsequent identity changes.']],lenses:{technical:'Correlate MFA resets, new device registration, sign-ins and remote-tool installation.',business:'Support staff need permission to pause a pressured executive request.',operations:'Call back using a verified directory number, not the number supplied in the request.'},steps:['Send help-desk reset approvals, identity changes and sign-in risk to the SOC.','Require additional verification and approval for privileged recovery actions.','Alert when a reset is followed by a new authenticator and unusual access.'],logic:'WHEN MFA_reset\nFOLLOWED BY new_authenticator + anomalous_sign_in\nWITHIN 60 minutes\nTHEN escalate and verify reset authorisation',test:'Exercise the process with an agreed fictional identity and no live reset.',noise:'Legitimate device replacement; retain evidence of approved recovery.',response:['Help desk · Pause and verify via the published recovery procedure.','Identity team · Revoke unauthorised registrations and sessions.','SOC · Investigate new access and installed remote tools.','Incident lead · Preserve evidence and notify affected owners.'],mission:['Find your actual organisation’s help-desk reporting route.','Draft a calm response to an urgent reset demand.','Rehearse one verified callback.'],quiz:{q:'Which phone number should be used for a sensitive callback?',a:['The number just supplied by the caller.','A previously verified directory or established contact.','The first number in a search advert.'],correct:1,why:'The callback must be independent of the suspicious request.'},sources:['spider','hygiene']},
{id:9,title:'When the attacker has an AI assistant',short:'AI at attack speed',category:'ai',icon:'sparkle',kind:'Provider investigation / assessment',minutes:6,
 summary:'Anthropic reports detecting an AI-orchestrated espionage campaign in September 2025 and disrupting it over about ten days. Its November report describes attempted intrusions across roughly thirty targets and a small number of successes. Attribution and automation estimates are provider assessments.',failure:'Faster, connected attack steps can outrun isolated alerts and slow ownership handoffs.',takeaway:'Connect the signals before the attacker connects the systems.',timeline:[['Mid-Sep 2025','Anthropic detects suspicious activity.'],['Following ten days','Investigation, account disruption and notifications.'],['13 Nov','The provider publishes its report.']],lenses:{technical:'Correlate identity, endpoint, network and data-access events; investigate chains rather than isolated hashes.',business:'Measure the time between a credible signal and an authorised containment decision.',operations:'Keep a staffed escalation path and a rehearsed way to suspend agent identities.'},steps:['Link events by identity, workload, asset and short time windows.','Alert on a sequence of unusual discovery, credential access and export behaviour.','Log agent tool calls and enforce separate, least-privilege service identities.'],logic:'WHEN unusual_discovery + credential_access + data_export\nSHARE identity_or_host WITHIN short_window\nTHEN raise correlated incident; require analyst assessment',test:'Replay a benign event sequence in a test workspace.',noise:'Authorised security testing must have documented scope and a known schedule.',response:['SOC · Validate the correlated chain and preserve evidence.','Identity owner · Suspend compromised human or workload access.','Platform owner · Restrict sensitive tools and egress.','Incident lead · Coordinate affected services, suppliers and reporting assessment.'],mission:['Name the owner of a fictional AI agent.','Choose one action it must not execute without approval.','Draw an escalation path from alert to containment.'],quiz:{q:'What should a provider’s attribution assessment be treated as?',a:['A conclusion about every incident in your environment.','An assessment to evaluate alongside your own evidence.','A reason to ignore ordinary access controls.'],correct:1,why:'Threat intelligence supplies context; local evidence establishes local impact.'},sources:['espionage']},
{id:10,title:'Your assistant should not have every key',short:'Agent permissions',category:'ai',icon:'key',kind:'Disclosed vulnerability',minutes:6,
 summary:'Anthropic’s August 2025 CVE-2025-55284 advisory describes a historical Claude Code allowlist flaw: untrusted context could induce file reads and network transmission without the expected confirmation. It was fixed in 1.0.4; the advisory says older clients were forced to update. This is a vulnerability disclosure, not proof of a victim breach.',failure:'Untrusted content reached tools whose permissions were too broad.',takeaway:'Put a real boundary around an agent’s tools.',timeline:[['Before 1.0.4','Historical versions are affected.'],['1.0.4','The maintainer identifies the patched version.'],['15 Aug 2025','The advisory is published.'],['Today','Use the current supported release, not a historical minimum.']],lenses:{technical:'Restrict readable directories, tool grants and outbound destinations. Keep secrets outside the workspace.',business:'Approve the agent’s purpose and maximum authority before connecting sensitive systems.',operations:'Know how to stop a run and revoke the agent’s credentials.'},steps:['Use a sandbox with a minimal filesystem view and scoped test credentials.','Require approval for consequential tools; enforce egress separately from prompt instructions.','Retain tool-call metadata with data minimisation; alert on sensitive file access followed by outbound activity.'],logic:'WHEN agent_reads_sensitive_test_path\nAND attempts_unapproved_outbound_destination\nTHEN deny egress + alert workload owner',test:'Use only a dummy secret and a controlled mock endpoint in an authorised sandbox.',noise:'Legitimate retrieval needs explicit, narrow grants. A prompt warning is not an access-control boundary.',response:['Operator · Stop the run and preserve tool logs.','Identity owner · Revoke exposed credentials.','SOC · Scope files read and network destinations.','Agent owner · Fix grants, update the client, and retest with synthetic data.'],mission:['List the minimum three tools a fictional assistant needs.','Remove one unnecessary permission.','Write a stop-and-revoke procedure.'],quiz:{q:'Which is an enforceable boundary?',a:['Ask the model to always be careful.','An isolated workspace, restricted tools and controlled egress.','Store an administrator token in the prompt.'],correct:1,why:'Instructions help behaviour; access control limits what tools can actually do.'},sources:['agent','genai']},
{id:11,title:'An AI key is a production credential',short:'Fake AI, real theft',category:'ai',icon:'gift',kind:'Provider threat report',minutes:5,
 summary:'Anthropic’s September 2026 threat report covers disrupted activity from December 2025 to August 2026, including malicious AI-service clients that harvested credentials or session tokens and abuse of stolen AI access. Findings reflect the provider’s visibility.',failure:'A convincing AI tool can become a credential-theft route; an API key can carry cost and data-access risk.',takeaway:'Verify the client. Scope the key. Watch the usage.',timeline:[['Dec 2025–Aug 2026','Activity covered by the provider report.'],['Sep 2026','The report is published.'],['Every installation','Verify the official distribution and approved business purpose.']],lenses:{technical:'Use per-workload keys, quotas and anomaly alerts; review endpoint evidence after suspected theft.',business:'Publish an approved-tool route so people are not pushed toward unofficial clients.',operations:'Reconcile unusual spend and usage; know who can revoke a key after hours.'},steps:['Record key owner, purpose, expiry, usage and approved source locations.','Alert on usage spikes, new sources and inactive keys becoming active; cap spending where supported.','Restrict unapproved installers and rotate suspected keys through an incident process.'],logic:'WHEN API_key_usage_is_unusual\nAND (new_source OR new_workload OR spend_spike)\nTHEN alert key owner; assess revocation',test:'Use a non-production key with a low quota and a simulated usage fixture.',noise:'A legitimate launch can spike usage; owners should annotate planned events.',response:['User · Stop the suspicious client and report its source.','Endpoint team · Preserve evidence and investigate credential access.','Key owner · Revoke affected keys and issue scoped replacements.','Incident lead · Review data access, spend and supplier notifications.'],mission:['Identify the official source for a tool you use.','Assign a fictional API key an owner and expiry.','Write a usage-alert recipient.'],quiz:{q:'What is the safest response to a suspected stolen AI API key?',a:['Rename it in a spreadsheet.','Revoke it, inspect usage and investigate the endpoint.','Post it publicly to ask whether it is valid.'],correct:1,why:'Revocation limits reuse; investigation addresses the original theft route.'},sources:['ai2026']},
{id:12,title:'Pause before you paste',short:'Everyday AI hygiene',category:'privacy',icon:'mug',kind:'Everyday practice',minutes:4,
 summary:'NIST’s Generative AI Profile discusses risks including confabulation and data privacy. A useful everyday habit is to minimise the data given to an AI service, verify important outputs, and understand where human review is needed. This lesson is a fictional workflow exercise.',failure:'Convenient copy-and-paste can expose unnecessary personal or confidential information, while plausible output can be wrong.',takeaway:'Use less data. Verify more carefully.',timeline:[['Before prompting','Check purpose, approved tool and data classification.'],['Before using output','Verify facts and decisions against trusted material.'],['After the task','Apply retention and access rules.']],lenses:{technical:'Use synthetic records for testing; evaluate retrieval permissions, retention and output handling.',business:'Set clear approved uses and escalation for consequential decisions.',operations:'Remove unnecessary names and identifiers, and check the source before forwarding an answer.'},steps:['Configure approved workspaces, least-privilege retrieval and proportionate retention.','Use data-classification and DLP controls where appropriate; do not copy raw sensitive prompts into general logs.','Keep human approval for consequential decisions and test the assistant with known-answer fixtures.'],logic:'WHEN sensitive_data_classification\nAND destination_not_approved_for_that_data\nTHEN block_or_warn + route exception to data owner',test:'Use synthetic personal data and a fake secret to test a DLP policy in audit mode first.',noise:'Pattern detectors can miss context and generate false positives; combine them with data classification.',response:['User · Stop sharing and report unintended disclosure.','Data owner · Establish what was sent and the service’s retention controls.','Security / privacy · Assess access, deletion and notification needs.','Process owner · Improve the approved workflow and training.'],mission:['Rewrite a fictional prompt without personal identifiers.','Check one AI answer against a primary source.','Identify the approved tool for confidential work.'],quiz:{q:'A fluent AI answer contains a source link. What next?',a:['Treat the link as proof without opening it.','Check that the source exists and supports the claim.','Forward it because the tone sounds confident.'],correct:1,why:'A plausible citation is not verification.'},sources:['genai','gdpr']},
{id:13,title:'The privacy clock starts with awareness',short:'The 72-hour clock',category:'privacy',icon:'clock',kind:'Regulation & reporting drill',minutes:7,
 summary:'Under GDPR Article 33, a controller notifies the competent supervisory authority without undue delay and, where feasible, within 72 hours of awareness, unless the breach is unlikely to pose a risk to people’s rights and freedoms. Processors notify controllers without undue delay. Article 34 has a separate high-risk communication duty and exceptions.',failure:'Teams can lose time debating complete certainty or confuse notifying an authority with notifying individuals.',takeaway:'Record awareness, assess risk, and keep the clock visible.',timeline:[['Awareness','Document when sufficient certainty of a personal-data breach exists.'],['Without undue delay','Processor escalates to controller; controller assesses notification.'],['Where feasible ≤72h','Controller notifies the competent authority when required.'],['High risk','Assess communication to affected people without undue delay under Article 34.']],lenses:{technical:'Preserve access and export evidence without spreading raw personal data.',business:'Assign a decision maker and document both report and no-report decisions.',operations:'Use the internal reporting route immediately; do not wait for a final forensic report.'},steps:['Create incident fields for awareness time, controller / processor role, affected data and people’s risk.','Set internal reminders earlier than the applicable deadline, and track phased updates and reasons for delay.','Restrict breach records; log notification decisions and evidence.'],logic:'WHEN suspected_personal_data_breach_created\nTHEN notify privacy lead; record awareness assessment\nIF report_required THEN track deadline + phased updates',test:'Run a paper drill with synthetic records and a fictional awareness timestamp.',noise:'Not every security event is a personal-data breach; a no-report decision still needs documented reasoning.',response:['Incident lead · Contain the incident and record awareness evidence.','DPO / legal · Determine roles, competent authority, risk and Article 34 applicability.','Authorised reporter · Submit through the verified authority channel if required; provide phased information if necessary.','Case owner · Record decisions, mitigation, communications and follow-up.'],mission:['Write a fictional awareness time and its 72-hour reference point.','List facts needed for an initial report.','Explain the difference between risk and high risk.'],quiz:{q:'Must a controller wait for a final forensic report before notifying?',a:['Yes, incomplete information cannot be submitted.','No. Assess the duty promptly; information may be provided in phases.','Only if the attacker is known.'],correct:1,why:'Article 33 permits phased information without undue further delay.'},sources:['gdpr','dpas']},
{id:14,title:'NIS2: report, respond, keep learning',short:'The 24 / 72 drill',category:'governance',icon:'bell',kind:'Directive & national rules',minutes:7,
 summary:'NIS2 Article 23 sets staged reporting for significant incidents: early warning within 24 hours, notification within 72 hours, and a final report within one month of that notification. Trust-service and ongoing-incident provisions require special handling. Applicability and routes depend on national implementation; sector-specific EU rules may take precedence.',failure:'Unclear scope, significance thresholds and ownership can delay both reporting and assistance.',takeaway:'Know your entity, threshold, authority and clock.',timeline:[['Awareness of significant incident','Start the applicable national process.'],['Within 24h','Early warning, without undue delay.'],['Within 72h','Incident notification; trust-service exception may be 24h.'],['One month after notification','Final report; ongoing incidents use the specified progress / final sequence.']],lenses:{technical:'Prepare severity, impact, indicators and mitigation evidence for reporting.',business:'Confirm entity scope and the relationship with sector-specific regimes such as DORA.',operations:'Verify the on-call reporter and the national CSIRT assistance channel.'},steps:['Map each legal entity to applicable national rules and competent authority.','Track significance assessment, awareness, early warning, notification and updates separately.','Exercise reporting with the authority’s agreed test method; never send a fictitious incident into a live portal without agreement.'],logic:'WHEN incident_meets_applicable_significance_threshold\nTHEN activate national reporting workflow\nTRACK awareness + early_warning + notification + follow_up',test:'Use a tabletop and a marked draft form. Request authority coordination before any live-channel exercise.',noise:'Deadlines are not permission to delay; local implementation and sector exceptions matter.',response:['Incident lead · Contain and assess operational impact.','Compliance owner · Confirm scope, significance and applicable national procedure.','Authorised reporter · Contact the verified CSIRT / authority and request assistance as needed.','Management · Maintain service continuity and review corrective actions.'],mission:['Choose a fictional entity and sector.','Find its national CSIRT through the directory.','Draft an early warning with unknowns clearly labelled.'],quiz:{q:'What is the correct planning approach?',a:['Use one universal reporting portal for every EU organisation.','Map entity scope, national implementation and sector rules first.','Wait 72 hours before escalating internally.'],correct:1,why:'NIS2 duties are implemented nationally and interact with sector-specific EU legislation.'},sources:['nis','csirts']},
{id:15,title:'Resilience belongs in the contract',short:'DORA & your suppliers',category:'governance',icon:'tree',kind:'Regulation · financial sector',minutes:7,
 summary:'DORA has applied since 17 January 2025 to covered financial entities. It addresses ICT risk and third-party dependencies. Contract requirements and tested exit planning matter. Delegated Regulation 2025/301 sets major-incident reporting clocks, including initial notification tied to both awareness and classification.',failure:'A critical supplier dependency can become an operational failure when evidence access, incident support or exit arrangements are missing.',takeaway:'Buy a recoverable service, not just an availability promise.',timeline:[['17 Jan 2025','DORA applies.'],['At major classification','Generally notify within 4h, and no later than 24h from awareness; later classification has a specific exception.'],['After initial notification','Intermediate report within 72h.'],['After intermediate / latest update','Final report within one month.']],lenses:{technical:'Maintain dependency maps, logging access, recovery tests and data-export capability.',business:'Review contracts for critical functions, subcontracting, audit rights and exit assistance.',operations:'Exercise one supplier outage and reconcile the reporting timeline with the competent authority’s procedure.'},steps:['Record ICT suppliers, supported functions, locations and accountable owners.','Monitor dependency health and retain evidence needed for major-incident classification.','Test an exit or continuity scenario against documented recovery objectives.'],logic:'WHEN critical_ICT_dependency_degraded\nTHEN assess business_impact + major_classification\nTRACK awareness and classification as distinct timestamps',test:'Use a fictional supplier outage and a draft reporting timeline; no live authority submission.',noise:'The late-classification exception and reporting updates require reading the full Article 5 rules.',response:['Service owner · Activate continuity and supplier escalation.','Incident lead · Record awareness, classification and impact.','Regulatory lead · Apply the competent authority’s reporting process.','Supplier manager · Preserve evidence and exercise contract and exit rights.'],mission:['Write three supplier contract questions.','Identify one concentration dependency.','Sketch an exit test that preserves customer service.'],quiz:{q:'Which two timestamps are essential for the initial DORA report?',a:['Awareness and major-incident classification.','Contract signature and invoice date.','First social post and first press article.'],correct:0,why:'Article 5 links the initial notification to awareness and classification, with a later-classification exception.'},sources:['dora','doraClock']},
{id:16,title:'Connected products need a support story',short:'The CRA countdown',category:'governance',icon:'gift',kind:'Regulation · phased duties',minutes:7,
 summary:'CRA reporting duties for manufacturers began on 11 September 2026. Main product requirements apply from 11 December 2027. Reporting covers actively exploited vulnerabilities and severe product-security incidents; final-report timing differs. Open-source software stewards’ relevant reporting duties apply from 11 December 2027.',failure:'Customers cannot maintain a secure product when support, updates and vulnerability handling have no clear owner.',takeaway:'Ask how a product stays secure after purchase.',timeline:[['11 Sep 2026 · already applies','Manufacturer reporting duties start.'],['Awareness · reporting','Early warning within 24h; full notification within 72h.'],['Final reports','Exploited vulnerability: 14 days after a corrective measure is available; severe incident: within a month of the 72h notification.'],['11 Dec 2027 · upcoming','Main CRA requirements apply; relevant steward reporting starts.']],lenses:{technical:'Maintain an inventory of components and support coordinated vulnerability disclosure; validate secure defaults.',business:'Ask about support periods, update delivery, vulnerability contacts and replacement costs.',operations:'Keep firmware, end-of-support and supplier contacts in the asset register.'},steps:['Link product versions and components to a named vulnerability-response owner.','Verify a supported update channel and a customer advisory process.','Prepare the CRA Single Reporting Platform workflow for applicable manufacturers.'],logic:'WHEN product_vulnerability_actively_exploited\nOR severe_product_security_incident\nTHEN assess CRA_scope + activate manufacturer reporting',test:'Use a synthetic product case and a draft notification; do not submit a fake report.',noise:'CRA product scope and roles require assessment; a purchaser is not automatically the manufacturer.',response:['Product security · Validate scope and exploitation evidence.','Manufacturer lead · Activate applicable SRP reporting.','Engineering · Mitigate, distribute trusted updates and document residual risk.','Customer support · Provide actionable guidance and support affected customers.'],mission:['Choose a fictional connected product.','Write a support and update checklist.','Distinguish manufacturer and customer response duties.'],quiz:{q:'Which CRA milestone is already active on 5 November 2026?',a:['Every main product requirement.','Manufacturer vulnerability and severe-incident reporting.','All open-source steward reporting duties.'],correct:1,why:'Manufacturer reporting started in September 2026; main requirements and relevant steward reporting follow in December 2027.'},sources:['cra','craDates','craLaw']},
{id:17,title:'AI rules: use the updated calendar',short:'AI Act dates & duties',category:'governance',icon:'clock',kind:'Amended EU implementation',minutes:7,
 summary:'The Commission says the AI Omnibus entered into force on 27 July 2026. Its current timeline includes a 2 December 2026 synthetic-content transition milestone and new prohibitions, 2 December 2027 for Annex III high-risk rules, and 2 August 2028 for Annex I product-embedded high-risk rules. The original rollout dates alone are no longer a reliable checklist.',failure:'A stale compliance calendar can assign the wrong duty, date or role.',takeaway:'Classify the use case before assigning the deadline.',timeline:[['2 Aug 2026 · already applies','Article 50 transparency rules start applying, with specified transitions.'],['2 Dec 2026 · upcoming','Certain pre-existing synthetic-content providers’ Article 50(2) transition ends; new prohibitions apply.'],['2 Dec 2027 · upcoming','Annex III high-risk rules apply.'],['2 Aug 2028 · upcoming','Annex I product-embedded high-risk rules apply.']],lenses:{technical:'Inventory systems, provider / deployer roles, synthetic outputs, logs and human oversight.',business:'Assign a legal owner and document classification; do not assume every AI system is high risk.',operations:'Check approved use, transparency notices and escalation whenever a workflow changes.'},steps:['Maintain an AI inventory with role, purpose, risk assessment and applicable milestone.','Version the compliance calendar against the amended official timeline.','Test synthetic-output marking and disclosure requirements where applicable.'],logic:'WHEN AI_use_case_or_provider_changes\nTHEN reassess role + risk_category + applicable_date\nREQUIRE documented owner review before deployment',test:'Classify a fictional recruitment tool and support chatbot using official guidance.',noise:'Dates do not determine scope by themselves; transitions and exceptions need case-specific review.',response:['AI owner · Identify systems and affected workflows.','Legal / compliance · Confirm current amended requirements and role.','Engineering · Prioritise controls and evidence for applicable milestones.','Operations · Update notices, training and change approval.'],mission:['Classify one fictional AI use case.','Identify provider and deployer roles.','Place its next applicable milestone on the calendar.'],quiz:{q:'Which date does the current Commission timeline give for Annex III high-risk rules?',a:['2 August 2026 for all systems without exception.','2 December 2027.','11 December 2027.'],correct:1,why:'The amended AI timeline gives 2 December 2027; CRA has a different December milestone.'},sources:['aiDates','omnibus','aiLaw']},
{id:18,title:'A human should know when to step in',short:'Practical AI literacy',category:'ai',icon:'sparkle',kind:'Everyday AI governance',minutes:5,
 summary:'The amended AI Act Article 4 requires providers and deployers to take measures supporting AI literacy for their staff and others operating AI systems on their behalf. Measures should reflect their knowledge, experience, context and affected people. The law does not require a guaranteed literacy level for each individual. Practise recognising unreliable outputs, sensitive data, unsuitable uses and escalation points.',failure:'A policy cannot protect a workflow if users do not know its limits.',takeaway:'Train for the decisions people actually make.',timeline:[['27 Jul 2026','AI Omnibus enters into force, according to the Commission.'],['Before use','Explain approved purpose, limits and human review.'],['After a change','Refresh training and test the new failure modes.']],lenses:{technical:'Build known-answer and misuse tests; verify controls after model and retrieval changes.',business:'Choose an accountable human for consequential outcomes and a measurable training objective.',operations:'Practise recognising a wrong answer and escalating without pressure to accept it.'},steps:['Publish approved-use examples and an escalation route near the task.','Measure whether staff can recognise sensitive inputs and unsupported conclusions.','Keep a reviewable record of changes, evaluations and corrective actions.'],logic:'WHEN consequential_AI_output\nAND human_review_missing\nTHEN hold decision and route to accountable reviewer',test:'Use three fictional outputs: correct, unsupported and privacy-invasive.',noise:'Attendance counts do not establish competence; evaluation should match the job.',response:['User · Pause the uncertain decision.','Reviewer · Check evidence and affected people.','AI owner · Investigate the failure and update controls.','Training owner · Rehearse the improved workflow.'],mission:['Write a plain-language limitation for an AI tool.','Choose a human escalation owner.','Correct a fictional confident but unsupported answer.'],quiz:{q:'What is the strongest measure of useful AI training?',a:['Everyone opened the slide deck.','People can recognise and handle the failure modes in their own work.','The policy contains many acronyms.'],correct:1,why:'Practical capability is demonstrated through task-relevant decisions.'},sources:['aiLaw','omnibus','genai','rmf']},
{id:19,title:'Turn a standard into a working habit',short:'ISO 27001 & CSF 2.0',category:'governance',icon:'shield',kind:'Standards & frameworks',minutes:6,
 summary:'ISO/IEC 27001:2022 concerns information-security management; ISO/IEC 27701:2025 covers privacy management for controllers and processors. NIST CSF 2.0 describes cybersecurity outcomes across Govern, Identify, Protect, Detect, Respond and Recover. A certifiable standard and a voluntary framework are different tools; neither is a substitute for incident evidence.',failure:'Checklists can measure paperwork while the actual control has no owner or proof.',takeaway:'Connect risk, control, owner, test and improvement.',timeline:[['2022','ISO/IEC 27001:2022 is published.'],['Feb 2024','NIST CSF 2.0 is published.'],['Each review cycle','Compare current outcomes with the target and track evidence gaps.']],lenses:{technical:'Choose a control and show its effective configuration plus a meaningful test result.',business:'Set a risk owner, acceptance criteria and review date.',operations:'Make control tasks repeatable, recorded and easy to escalate when they fail.'},steps:['Create a risk-to-control record with scope, owner and evidence.','Monitor control health, including missing log feeds and failed backups.','Use a current / target profile to prioritise gaps; consult licensed ISO text for exact requirements.'],logic:'WHEN control_evidence_missing OR control_test_failed\nTHEN create owned corrective_action + due_date\nESCALATE overdue material risk',test:'Select one synthetic backup job and show that a restore test, not only a success email, is reviewed.',noise:'An overdue task is not automatically a breach; prioritise by consequence.',response:['Control owner · Validate the failure.','Risk owner · Decide mitigation and interim measures.','Operations · Restore the control and preserve evidence.','Assurance · Retest and record improvement.'],mission:['Write one risk in plain language.','Map it to a CSF outcome and an owner.','Define evidence that would prove the control works.'],quiz:{q:'Which record best demonstrates a working control?',a:['A policy title without an owner.','Owner, configuration, test result and corrective action.','A certificate used as proof that no incidents can occur.'],correct:1,why:'Evidence and improvement connect governance with actual behaviour.'},sources:['iso27001','iso27701','csf']},
{id:20,title:'Govern the AI, not just the model',short:'ISO 42001 & AI RMF',category:'governance',icon:'tree',kind:'AI standards & frameworks',minutes:6,
 summary:'ISO/IEC 42001:2023 addresses an AI management system. NIST AI RMF 1.0 organises risk work through Govern, Map, Measure and Manage. The practices apply across people, data, suppliers and lifecycle changes, not only a model’s accuracy. These are standards / guidance, not a blanket declaration of legal compliance.',failure:'A model update or new data connector can change a previously evaluated system.',takeaway:'Manage the whole AI lifecycle.',timeline:[['Jan 2023','NIST AI RMF 1.0 is published.'],['2023','ISO/IEC 42001:2023 is published.'],['Every material change','Re-evaluate system risk and deployment approval.']],lenses:{technical:'Version datasets, retrieval access, model settings, evaluations and rollback plans.',business:'Name the system owner and acceptable impact; include supplier dependencies.',operations:'Track user feedback, incidents and drift in the actual service.'},steps:['Keep an AI inventory, risk assessment and change record.','Define measurable tests for privacy, security, reliability and human oversight.','Require material-change review and rollback evidence.'],logic:'WHEN model_or_data_or_tool_permission_changes\nTHEN run relevant_evaluations + owner_review\nIF acceptance_failed THEN hold_release',test:'Use a synthetic model-change request with one deliberately failed privacy test.',noise:'Not every parameter change has equal impact; define materiality and documented exceptions.',response:['AI owner · Pause the affected release or workflow.','Evaluation lead · Reproduce the failure safely.','Business owner · Assess affected decisions and users.','Change lead · Correct, retest and approve a controlled rollout.'],mission:['Write a one-line purpose for a fictional AI system.','Choose one measurable failure threshold.','Define a rollback decision owner.'],quiz:{q:'When should a new data connector trigger review?',a:['Only after an incident.','When it materially changes access, data or system risk.','Never, because the model name is unchanged.'],correct:1,why:'The deployed system includes data and tools as well as the model.'},sources:['iso42001','rmf']},
{id:21,title:'Sensitive data deserves an earlier alarm',short:'The 23andMe lesson',category:'privacy',icon:'bell',kind:'Regulatory enforcement finding',minutes:6,
 summary:'The UK ICO announced a £2.31 million fine against 23andMe in June 2025 over security failures linked to the 2023 attack. Its findings address inadequate authentication, monitoring and incident investigation. The case illustrates why highly sensitive data needs proportionate protection and a decisive escalation path.',failure:'Credential attacks and warning signs were not met with adequate safeguards and investigation.',takeaway:'A suspicious signal deserves an accountable decision.',timeline:[['Apr 2023','Credential stuffing begins using login credentials stolen in unrelated breaches.'],['May 2023','The first period of intense credential-stuffing activity occurs.'],['Jul 2023','23andMe conducts isolated investigations into unauthorised activity.'],['Aug 2023','A claim of data theft affecting over 10 million users is dismissed as a hoax. This was a claim, not a verified affected-person count.'],['Sep 2023','Another wave of credential stuffing follows.'],['Oct 2023','A full investigation begins after an employee finds stolen data advertised for sale on Reddit.'],['17 Jun 2025','The ICO announces its £2.31 million fine.']],lenses:{technical:'Detect credential stuffing and unusual relationship-data access without relying only on failed logins.',business:'Treat potential harm to people as part of incident severity.',operations:'Record warning signs and escalate unresolved concerns through a named route.'},steps:['Correlate failed and successful authentication with device, source and access patterns.','Use risk-based rate controls, strong authentication and unusual-access alerts.','Route sensitive-data incidents to security and privacy leads; preserve the initial signals.'],logic:'WHEN distributed_login_anomaly\nOR successful_access_to_sensitive_records_is_unusual\nTHEN investigate account_takeover + data_access_scope',test:'Replay synthetic authentication events; never perform credential stuffing against a real service.',noise:'Shared networks and accessibility needs require careful tuning and human review.',response:['Security · Protect accounts and preserve authentication evidence.','Data owner · Scope sensitive data and affected people.','Privacy lead · Assess reporting and communications under the applicable jurisdiction.','Management · Address root causes and verify that corrective actions are effective.'],mission:['Identify one sensitive-data workflow.','Name the escalation owner for a weak warning signal.','Explain potential harm without listing real personal data.'],quiz:{q:'Which metric is insufficient by itself?',a:['A count of failed logins without successful-access context.','A reviewed access timeline.','An investigation with data-owner input.'],correct:0,why:'Successful misuse and data access can matter more than the raw failed-login count.'},sources:['ico','hygiene']},
{id:22,title:'Call the right people, rehearse the right way',short:'Report & test safely',category:'governance',icon:'key',kind:'Authority & testing workshop',minutes:7,
 summary:'Technical assistance, legal notification and criminal reporting serve different purposes. A CSIRT, data-protection authority, sector regulator, product-reporting platform and law enforcement may each have a role. Testing requires explicit scope and authorisation; a disclosure policy is not permission to test every supplier system.',failure:'A team can report to the wrong recipient or accidentally turn a drill into a real-world disruption.',takeaway:'Agree the route and the rules before the incident.',timeline:[['Before testing','Written scope, permission, data rules and stop conditions.'],['At an incident','Contain, preserve evidence and assess the relevant notification regimes.'],['During the exercise','Use labelled drafts or an authority-agreed exercise channel.'],['Afterwards','Debrief, assign improvements and retest.']],lenses:{technical:'Use a controlled lab and synthetic telemetry; stop on unexpected access or impact.',business:'Approve rules of engagement, supplier consent and reporting authority.',operations:'Keep verified contacts offline and practise a handoff with a factual timeline.'},steps:['Define target assets, test methods, dates, contacts, evidence handling and emergency stop.','Verify authority and supplier reporting channels from official directories.','Keep production reporting separate from clearly labelled exercise artefacts.'],logic:'IF target_not_explicitly_in_scope OR authority_not_granted\nTHEN do_not_test; request scope clarification\nIF unexpected_impact THEN stop + notify test coordinator',test:'Conduct a paper exercise and replay synthetic alerts only.',noise:'No calendar task authorises scanning, exploiting or reporting against third-party systems.',response:['Incident lead · Record facts, impact, unknowns and assistance required.','Legal / privacy · Determine applicable statutory recipients and clocks.','Authorised reporter · Use verified channels; preserve receipt and case reference.','Exercise coordinator · Agree any authority participation in advance and label exercise material.'],mission:['Draft five rules of engagement for a lab.','Find a CSIRT and DPA using official directories.','Write a clear stop condition and exercise label.'],quiz:{q:'Can a customer test a supplier’s systems merely because it buys the service?',a:['Yes, payment grants testing permission.','No. Explicit authorisation and agreed scope are needed.','Yes, if the test happens at night.'],correct:1,why:'Customer status is not a grant of security-testing authority.'},sources:['vdp','csirts','dpas','cra']},
{id:23,title:'Turn a headline into a coverage check',short:'Threat intel that works',category:'cyber',icon:'star',kind:'Threat-intelligence workshop',minutes:6,
 summary:'A refrigeration advisory is useful to a retailer, a facilities supplier and a business buying cold-chain services. Good threat intelligence connects the reported behaviour to your assets, dependencies, controls and response owner. FIRST TLP 2.0 provides sharing boundaries; those boundaries do not replace privacy and contractual obligations.',failure:'Collecting indicators without validating exposure, telemetry or ownership leaves a coverage gap.',takeaway:'Every relevant advisory should end with an owned action.',timeline:[['Receive','Record source, date, confidence and handling label.'],['Assess','Match products, versions and supplier dependencies.'],['Act','Assign mitigation, detection and a response owner.'],['Validate','Run a safe test, measure coverage and feed back findings.']],lenses:{technical:'Map behaviours to available telemetry; expire indicators and test detections.',business:'Ask for coverage evidence and residual risk, not a count of subscribed feeds.',operations:'Include maintenance suppliers and customer obligations in the action list.'},steps:['Triage advisories against an owned asset and supplier inventory.','Record telemetry gaps, mitigation status, due dates and detection validation.','Share sanitised evidence through approved channels using the correct TLP label.'],logic:'FOR each relevant_advisory\nMATCH owned_assets + supplier_dependencies\nASSIGN mitigation + detection + response_owner\nVERIFY evidence; expire stale indicators',test:'Use the public refrigeration advisory and a fictional three-site inventory.',noise:'An IOC match needs investigation; absence of a match does not prove absence of compromise.',response:['Intel analyst · Validate source and relevance.','Asset / supplier owner · Confirm exposure and business consequence.','Detection engineer · Implement detections for the relevant behaviour and validate them safely.','Incident lead · Share actionable findings within approved handling limits.'],mission:['Match one public advisory to a fictional asset.','Identify one telemetry gap and owner.','Choose a correct sharing label and expiry date.'],quiz:{q:'Where may TLP:AMBER+STRICT information be shared by default?',a:['On LinkedIn with a warning.','Inside the recipient organisation only.','With any customer of a recipient.'],correct:1,why:'FIRST restricts AMBER+STRICT to the recipient organisation; wider sharing needs source permission.'},sources:['tlp','enisa','nis']},
{id:24,title:'Keep the lights on, together',short:'The winter resilience quest',category:'cyber',icon:'tree',kind:'Fictional team tabletop',minutes:10,
 summary:'Fictional scenario: a cold-chain supplier reports a compromised remote-access account. Your AI support assistant can read maintenance tickets containing personal data. A customer notices unexplained temperature alarms. Use what you learned to protect operations, contain identity access, assess data exposure and coordinate reporting.',failure:'Unowned dependencies and disconnected response teams can turn one compromised identity into several business impacts.',takeaway:'Resilience is a team sport, all year round.',timeline:[['T+0 · inject','Supplier reports possible account compromise; confidence is incomplete.'],['T+15 min · inject','A site alarm appears; independent readings need checking.'],['T+30 min · inject','An AI connector’s logs suggest unusual ticket access.'],['Debrief','Assess decisions, reporting clocks and untested assumptions.']],lenses:{technical:'Preserve evidence, suspend scoped access and validate agent and OT boundaries.',business:'Choose a clear incident commander and communicate knowns and unknowns.',operations:'Keep people and goods safe, coordinate facilities, and maintain a manual fallback.'},steps:['Use paper injects and synthetic logs only; pre-agree participants and stop conditions.','Track safety, service continuity, identity, privacy and supplier workstreams.','Assess each reporting regime independently; avoid assuming one notification covers them all.'],logic:'WHEN tabletop_inject_received\nRECORD facts + uncertainty + owner + decision_time\nCHECK safety + containment + privacy + reporting + recovery',test:'Run a 20-minute tabletop, then a 10-minute debrief. No production changes or real authority notifications.',noise:'This is a fictional composite scenario, not a claim that the real fridge campaign involved AI.',response:['Facilities lead · Confirm safe operation using independent readings.','SOC / identity · Restrict supplier and agent access; preserve evidence.','Privacy / regulatory lead · Assess entity roles, affected data, significance and clocks.','Incident commander · Coordinate supplier, customer and authority handoffs; approve monitored recovery.'],mission:['Record three decisions and accountable owners.','Draft a sanitised customer update that distinguishes facts from unknowns.','Assign one measurable improvement and a retest date.'],quiz:{q:'What should happen before a rehearsed authority notification?',a:['Submit a fictional incident through the live portal without warning.','Agree participation and exercise channels, or use a clearly labelled draft.','Post the supplier’s access logs publicly.'],correct:1,why:'A drill must not create a false live incident or disclose sensitive evidence.'},sources:['enisa','agent','gdpr','nis','doraClock','vdp']}
];

