// Original read-only hunting example. Schema verified against Microsoft documentation.
window.WINTERWATCH_LESSONS[4].hunt = {
 title:'Microsoft Defender XDR · read-only hunting example',
 setup:'Relevant hosts must be onboarded to Defender for Endpoint, and DeviceProcessEvents must contain data. Run in Advanced Hunting, limit to your SharePoint asset group, review legitimate IIS activity, then tune. This query has not been executed against a live tenant.',
 code:`DeviceProcessEvents
| where Timestamp > ago(1d)
| where InitiatingProcessFileName =~ "w3wp.exe"
| where FileName in~ ("cmd.exe", "powershell.exe", "pwsh.exe")
| project Timestamp, DeviceName, InitiatingProcessFileName, FileName, ProcessCommandLine
| order by Timestamp desc`
};
